\begin{aligned}
\mathrm{ELBO}[\phi_{1\ldots T}] &= \int q(\mathbf{z}_{1\ldots T}|\mathbf{x}) \log\left[\frac{Pr(\mathbf{x},\mathbf{z}_{1\ldots T}|\phi_{1\ldots T})}{q(\mathbf{z}_{1\ldots T}|\mathbf{x})}\right] d\mathbf{z}_{1\ldots T} \\
&\approx \int q(\mathbf{z}_{1\ldots T}|\mathbf{x}) \left( \log\left[Pr(\mathbf{x}|\mathbf{z}_1,\phi_1)\right] + \sum_{t=2}^{T} \log\left[\frac{Pr(\mathbf{z}_{t-1}|\mathbf{z}_t,\phi_t)}{q(\mathbf{z}_{t-1}|\mathbf{z}_t,\mathbf{x})}\right] \right) d\mathbf{z}_{1\ldots T} \\
&= \mathbb{E}_{q(\mathbf{z}_1|\mathbf{x})}\left[\log\left[Pr(\mathbf{x}|\mathbf{z}_1,\phi_1)\right]\right] - \sum_{t=2}^{T} \mathbb{E}_{q(\mathbf{z}_{t,t-1}|\mathbf{x})}\left[\mathrm{D}_{KL}\left[q(\mathbf{z}_{t-1}|\mathbf{z}_t,\mathbf{x})\big\| Pr(\mathbf{z}_{t-1}|\mathbf{z}_t,\phi_t)\right]\right],
\end{aligned}

